   207|async function walkInspectableFiles(relDir: string, results: string[], max: number, projectRoot: string): Promise<void> {
   208|  if (results.length >= max) return;
   209|  const absDir = path.join(projectRoot, relDir);
   210|  let entries: string[];
   211|  try {
   212|    entries = await readdir(absDir);
   213|  } catch {
   214|    return;
   215|  }
   216|  for (const entry of entries) {
   217|    if (results.length >= max) return;
   218|    const relEntry = relDir ? `${relDir}/${entry}` : entry;
   219|    const absEntry = path.join(absDir, entry);
   220|    let info;
   221|    try {
