   239|function pickInspectionTargets(goal: string, availableFiles: string[]): string[] {
   240|  const alwaysInclude = [
   241|    'backend/services/ivx-autonomous-coder-pilot.ts',
   242|    'backend/services/ivx-senior-developer-worker.ts',
   243|    'backend/services/ivx-senior-developer-runtime.ts',
   244|    'backend/ivx-ai-runtime.ts',
   245|    'backend/api/ivx-owner-ai.ts',
   246|    'backend/hono.ts',
   247|    'render.yaml',
   248|    'package.json',
   249|  ].filter((f) => availableFiles.includes(f));
   250|
   251|  const words = Array.from(new Set(
   252|    goal.toLowerCase()
   253|      .replace(/[^a-z0-9\s]/g, ' ')
   254|      .split(/\s+/)
   255|      .filter((w) => w.length >= 4)
   256|      .filter((w) => !['that', 'this', 'with', 'from', 'have', 'please', 'change', 'deploy', 'anything', 'current', 'status', 'label', 'version'].includes(w)),
   257|  ));
