   269|async function readFilePreview(relPath: string, projectRoot: string): Promise<{ path: string; content: string; bytes: number } | null> {
   270|  try {
   271|    const absPath = path.join(projectRoot, relPath);
   272|    const content = await readFile(absPath, 'utf8');
   273|    const bytes = Buffer.byteLength(content, 'utf8');
   274|    // Send full content for small files so the LLM can copy oldText verbatim.
   275|    const preview = bytes <= FULL_CONTENT_THRESHOLD ? content : truncate(content, FILE_PREVIEW_CHARS);
   276|    return { path: relPath, content: preview, bytes };
   277|  } catch {
