   282|// ── PATCH APPLICATION ────────────────────────────────────────────────────────
   283|
   284|/** Paths the autonomous coder is allowed to modify. */
   285|const ALLOWED_PATCH_PATHS = /^((?:backend|expo)\/[A-Za-z0-9_.\/-]+\.ts$|(?:backend|expo)\/[A-Za-z0-9_.\/-]+\.tsx$|expo\/[A-Za-z0-9_.\/-]+\.json$|expo\/[A-Za-z0-9_.\/-]+\.gradle$)/;
   286|
   287|function assertSafePatchPath(filePath: string): void {
   288|  if (filePath.includes('..') || filePath.startsWith('/')) {
   289|    throw new Error(`Unsafe patch path rejected: ${filePath}`);
   290|  }
   291|  if (!ALLOWED_PATCH_PATHS.test(filePath)) {
   292|    throw new Error(`Patch path outside allowed roots: ${filePath}. Only backend/*.ts, expo/*.ts(x), expo/*.json, expo/*.gradle are permitted.`);
   293|  }
