   296|async function applyPatchOperation(
   297|  op: IVXAutonomousCoderPatchOperation,
   298|  projectRoot: string,
   299|  fileWriter?: (relPath: string, content: string) => Promise<void>,
   300|  fileReader?: (relPath: string) => Promise<string>,
   301|): Promise<void> {
   302|  assertSafePatchPath(op.path);
   303|  const fullPath = path.join(projectRoot, op.path);
   304|  const write = fileWriter ?? (async (rel: string, content: string) => {
   305|    await mkdir(path.dirname(path.join(projectRoot, rel)), { recursive: true });
   306|    await writeFile(path.join(projectRoot, rel), content, 'utf8');
   307|  });
   308|  const read = fileReader ?? (async (rel: string) => readFile(path.join(projectRoot, rel), 'utf8'));
   309|  if (op.kind === 'create_file') {
   310|    const { existsSync } = await import('node:fs');
   311|    if (existsSync(fullPath)) {
   312|      throw new Error(`Create-file target already exists: ${op.path}`);
   313|    }
   314|    await write(op.path, op.newText);
   315|  } else {
   316|    const source = await read(op.path);
   317|    if (!source.includes(op.oldText)) {
   318|      throw new Error(`Patch oldText not found in ${op.path}; cannot apply safely.`);
   319|    }
   320|    const updated = source.replace(op.oldText, op.newText);
   321|    await write(op.path, updated);
   322|  }
   323|}
   324|
   325|async function revertPatchOperation(
   326|  op: IVXAutonomousCoderPatchOperation,
   327|  projectRoot: string,
   328|  fileWriter?: (relPath: string, content: string) => Promise<void>,
   329|  fileReader?: (relPath: string) => Promise<string>,
