   332|    await mkdir(path.dirname(path.join(projectRoot, rel)), { recursive: true });
   333|    await writeFile(path.join(projectRoot, rel), content, 'utf8');
   334|  });
   335|  const read = fileReader ?? (async (rel: string) => readFile(path.join(projectRoot, rel), 'utf8'));
   336|  if (op.kind === 'create_file') {
   337|    try { await rm(path.join(projectRoot, op.path)); } catch { /* already gone */ }
   338|  } else {
   339|    try {
   340|      const source = await read(op.path);
   341|      if (source.includes(op.newText)) {
   342|        await write(op.path, source.replace(op.newText, op.oldText));
   343|      }
   344|    } catch { /* file may not exist */ }
   345|  }
