   348|// ── TEST + TYPECHECK RUNNER ──────────────────────────────────────────────────
   349|
   350|async function runCommand(cwd: string, command: string): Promise<IVXAutonomousCoderTestResult> {
   351|  const started = Date.now();
   352|  // Resolve the runtime: the Render container runs under node+tsx, not bun.
   353|  // `bun test` and `bun x tsc` fail with ENOENT on the production container, so
   354|  // we resolve the runtime via resolveRuntimeCommand and translate the command
   355|  // to its node-based equivalent when bun is not available.
   356|  const parts = command.split(/\s+/);
   357|  const requestedRuntime = parts[0] as 'bun' | 'bunx' | 'node' | 'npx';
   358|  const resolution = resolveRuntimeCommand(requestedRuntime);
   359|  let effectiveCmd = resolution.resolvedPath ?? resolution.effectiveCommand;
   360|  let effectiveArgs = parts.slice(1);
   361|  let displayCommand = command;
   362|  // When bun falls back to node, translate `bun test <file>` → `node --test <file>`
   363|  // (node:test runner) and `bun x tsc --noEmit` → `npx tsc --noEmit` (or node tsc).
   364|  if (resolution.usedFallback && requestedRuntime === 'bun') {
   365|    if (effectiveArgs[0] === 'test') {
   366|      effectiveArgs = ['--test', ...effectiveArgs.slice(1)];
   367|      displayCommand = `node --test ${effectiveArgs.slice(1).join(' ')}`;
   368|    } else if (effectiveArgs[0] === 'x') {
   369|      // `bun x tsc` → use npx instead
   370|      const npxRes = resolveRuntimeCommand('npx');
   371|      effectiveCmd = npxRes.resolvedPath ?? npxRes.effectiveCommand;
   372|      effectiveArgs = effectiveArgs.slice(1); // drop the 'x'
   373|      displayCommand = `npx ${effectiveArgs.join(' ')}`;
   374|    }
   375|  }
   376|  try {
   377|    const result = await execFileAsync(effectiveCmd, effectiveArgs, {
   378|      cwd,
   379|      timeout: COMMAND_TIMEOUT_MS,
   380|      maxBuffer: 1024 * 1024 * 4,
   381|      env: { ...process.env, CI: '1', FORCE_COLOR: '0' },
   382|    });
   383|    return {
   384|      command: displayCommand,
   385|      ok: true,
   386|      exitCode: 0,
   387|      stdoutTail: truncate(typeof result.stdout === 'string' ? result.stdout : '', 2000),
   388|      stderrTail: truncate(typeof result.stderr === 'string' ? result.stderr : '', 2000),
   389|      durationMs: Date.now() - started,
   390|    };
   391|  } catch (error) {
   392|    const err = error as { code?: number; stdout?: string; stderr?: string; signal?: string };
   393|    return {
   394|      command: displayCommand,
   395|      ok: false,
   396|      exitCode: typeof err.code === 'number' ? err.code : null,
   397|      stdoutTail: truncate(typeof err.stdout === 'string' ? err.stdout : '', 2000),
   398|      stderrTail: truncate(typeof err.stderr === 'string' ? err.stderr : '', 2000),
   399|      durationMs: Date.now() - started,
   400|    };
   401|  }
   402|}
