   404|/** Pick the most relevant test file for the goal. */
   405|function pickTargetTestFile(goal: string, changedFiles: string[]): string {
   406|  // If a changed file has a corresponding .test.ts, run it.
   407|  for (const changed of changedFiles) {
   408|    const testFile = changed.replace(/\.ts$/, '.test.ts').replace(/^backend\//, 'backend/');
   409|    if (testFile !== changed) {
   410|      // Check if the test file path matches a known test pattern
   411|      return testFile;
   412|    }
   413|  }
   414|  // Default: run the autonomous coder's own tests
   415|  return 'backend/ivx-autonomous-coder.test.ts';
   416|}
