   418|// ── LLM PATCH GENERATION ─────────────────────────────────────────────────────
   419|
   420|const PATCH_SYSTEM_PROMPT = `You are the IVX Autonomous Coder — a real senior developer engine.
   421|Given a GOAL and FILE CONTENTS, generate a JSON patch to achieve the goal.
   422|
   423|OUTPUT FORMAT (strict JSON, no markdown, no prose):
   424|{
   425|  "rootCause": "one-line root cause",
   426|  "technicalPlan": "one-line plan",
   427|  "operations": [
   428|    {
   429|      "path": "backend/services/example.ts",
   430|      "kind": "replace_exact",
   431|      "oldText": "the exact text to find",
   432|      "newText": "the replacement text",
   433|      "reason": "why this change"
   434|    }
   435|  ]
   436|}
   437|
   438|Rules:
   439|- kind must be "replace_exact" (replace oldText with newText) or "create_file" (new file).
   440|- oldText must be an EXACT substring of the file content (copy it verbatim).
   441|- Make the smallest safe change.
   442|- Only modify files under backend/ or expo/.
   443|- No secrets, no destructive operations.`;
   444|
   445|function buildPatchUserPrompt(goal: string, files: { path: string; content: string }[], failureContext: string | null): string {
   446|  const fileBlocks = files.map((f) => `--- FILE: ${f.path} ---\n${f.content}`).join('\n\n');
   447|  const failureBlock = failureContext
   448|    ? `\n\n--- PREVIOUS ATTEMPT FAILED ---\n${failureContext}\n\nRevise the patch to fix the failure. Output the corrected JSON.`
   449|    : '';
   450|  return `GOAL:\n${goal}\n\nFILES:\n${fileBlocks}${failureBlock}`;
   451|}
   452|
   453|function parseLLMPatchResponse(response: string): { rootCause: string; technicalPlan: string; operations: IVXAutonomousCoderPatchOperation[] } | null {
   454|  try {
   455|    // Strip markdown code fences if present
   456|    const cleaned = response.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
   457|    // Find the first { and last }
   458|    const start = cleaned.indexOf('{');
   459|    const end = cleaned.lastIndexOf('}');
   460|    if (start < 0 || end < 0 || end <= start) return null;
   461|    const jsonStr = cleaned.slice(start, end + 1);
   462|    const parsed = JSON.parse(jsonStr) as {
   463|      rootCause?: string;
   464|      technicalPlan?: string;
   465|      operations?: Array<{
   466|        path?: string;
   467|        kind?: string;
   468|        oldText?: string;
   469|        newText?: string;
   470|        reason?: string;
   471|      }>;
   472|    };
   473|    if (!Array.isArray(parsed.operations)) return null;
   474|    const operations: IVXAutonomousCoderPatchOperation[] = [];
   475|    for (const op of parsed.operations) {
   476|      if (typeof op.path !== 'string' || typeof op.kind !== 'string') continue;
   477|      if (op.kind !== 'replace_exact' && op.kind !== 'create_file') continue;
   478|      if (typeof op.oldText !== 'string' || typeof op.newText !== 'string') continue;
   479|      operations.push({
   480|        path: op.path,
   481|        kind: op.kind,
   482|        oldText: op.oldText,
   483|        newText: op.newText,
   484|        reason: typeof op.reason === 'string' ? op.reason : '',
   485|      });
   486|    }
   487|    if (operations.length === 0) return null;
   488|    return {
   489|      rootCause: typeof parsed.rootCause === 'string' ? parsed.rootCause : 'LLM-generated patch',
   490|      technicalPlan: typeof parsed.technicalPlan === 'string' ? parsed.technicalPlan : 'Replace exact text per operations',
   491|      operations,
   492|    };
   493|  } catch {
   494|    return null;
   495|  }
   496|}
