   498|/** Promise-race timeout wrapper so the LLM call can never hang the loop. */
   499|function withTimeout<T>(promise: Promise<T>, ms: number, label: string): Promise<T> {
   500|  return Promise.race([
   501|    promise,
   502|    new Promise<T>((_, reject) => {
   503|      setTimeout(() => reject(new Error(`${label} timed out after ${ms}ms`)), ms);
   504|    }),
   505|  ]);
   506|}
