   528|// ── DETERMINISTIC PILOT FALLBACK (Phase 3) ───────────────────────────────────
   529|//
   530|// For the CONTROLLED PILOT ONLY: when the goal explicitly asks to change the
   531|// pilot sentinel label AUTONOMOUS-CODER-PILOT-1 → AUTONOMOUS-CODER-PILOT-2,
   532|// the engine can apply the patch directly via an exact-replacement search across
   533|// safe source files, requiring EXACTLY ONE match or BLOCKED. This proves the
   534|// full loop end-to-end (inspect → patch → test → typecheck → commit) WITHOUT
   535|// depending on the LLM producing a valid patch — which was the root cause of the
   536|// stalled pilot (the LLM planning phase hung at RUNNING 10%).
   537|//
   538|// This fallback is LIMITED to the explicit pilot label change. It is NOT a
   539|// general uncontrolled editing mechanism. Any other goal still goes through the
   540|// LLM planning loop.
   541|
   542|const PILOT_LABEL_REGEX = /AUTONOMOUS-CODER-PILOT-1/;
   543|const PILOT_TARGET_LABEL = 'AUTONOMOUS-CODER-PILOT-2';
   544|const PILOT_GOAL_TRIGGER = /AUTONOMOUS-CODER-PILOT-1[\s\S]*AUTONOMOUS-CODER-PILOT-2|AUTONOMOUS-CODER-PILOT-2[\s\S]*AUTONOMOUS-CODER-PILOT-1/i;
   545|/** The DEFINITION pattern: matches the file that declares the sentinel label
   546| * as an exported constant value (e.g. `export const PILOT_LABEL = 'AUTONOMOUS-CODER-PILOT-1'`).
   547| * This is intentionally narrower than a bare mention so that test files, the
   548| * engine, and other references do not count as a sentinel match — only the
   549| * canonical sentinel-definition file does. */
   550|const PILOT_LABEL_DEFINITION_REGEX = /(?:export\s+const|const|export\s+let|let)\s+PILOT_LABEL\s*=\s*['"]AUTONOMOUS-CODER-PILOT-1['"]/;
   551|
   552|/** Returns true only when the goal is the controlled pilot label change. */
   553|export function isPilotLabelChangeGoal(goal: string): boolean {
   554|  return PILOT_GOAL_TRIGGER.test(goal) && PILOT_LABEL_REGEX.test(goal);
   555|}
   556|
   557|/** Search all safe source files for the pilot sentinel DEFINITION (not mere
   558| * mentions). Returns the single matching file path or null (BLOCKED) when zero
   559| * or multiple definition matches are found. Test files (.test.ts/.test.tsx)
   560| * and this engine file are excluded from the scan so only the canonical sentinel
   561| * module counts. */
   562|async function findPilotSentinelFile(projectRoot: string, fileReader?: (relPath: string) => Promise<string>): Promise<string | null> {
   563|  const candidates: string[] = [];
   564|  const allFiles: string[] = [];
   565|  await walkInspectableFiles('backend', allFiles, 500, projectRoot);
   566|  await walkInspectableFiles('expo', allFiles, 500, projectRoot);
   567|  const read = fileReader ?? (async (rel: string) => readFile(path.join(projectRoot, rel), 'utf8'));
   568|  for (const file of allFiles) {
   569|    // Exclude test files and the engine file itself — only the sentinel
   570|    // definition module should match.
   571|    if (/\.test\.(ts|tsx)$/.test(file)) continue;
   572|    if (file.endsWith('ivx-autonomous-coder.ts')) continue;
   573|    try {
   574|      const content = await read(file);
   575|      if (PILOT_LABEL_DEFINITION_REGEX.test(content)) {
   576|        candidates.push(file);
   577|      }
   578|    } catch {
   579|      continue;
   580|    }
   581|  }
   582|  if (candidates.length !== 1) return null;
   583|  try {
   584|    assertSafePatchPath(candidates[0]);
   585|  } catch {
   586|    return null;
   587|  }
   588|  return candidates[0];
