   591|/** Deterministic pilot fallback: produces the exact-replacement patch for the
   592| * pilot label change without calling the LLM. Returns the patch operation or
   593| * null (BLOCKED) when the sentinel cannot be located uniquely. */
   594|async function deterministicPilotFallback(
   595|  projectRoot: string,
   596|  fileReader?: (relPath: string) => Promise<string>,
   597|): Promise<{ rootCause: string; technicalPlan: string; operations: IVXAutonomousCoderPatchOperation[]; sentinelFile: string } | null> {
   598|  const sentinelFile = await findPilotSentinelFile(projectRoot, fileReader);
