   610|    rootCause: 'Controlled pilot: the repository contains a single sentinel-label definition that must be changed to prove the loop end-to-end.',
   611|    technicalPlan: 'Apply an exact-replacement of the PILOT_LABEL definition value (AUTONOMOUS-CODER-PILOT-1 -> AUTONOMOUS-CODER-PILOT-2) in the single matching sentinel-definition file, then run targeted tests + typecheck + commit.',
   612|    operations: [{
   613|      path: sentinelFile,
   614|      kind: 'replace_exact',
   615|      oldText,
   616|      newText,
   617|      reason: 'Pilot proof: change the visible version label per the owner mandate.',
   618|    }],
   619|    sentinelFile,
   620|  };
