   624|
   625|const GITHUB_API_BASE_URL = 'https://api.github.com';
   626|const GITHUB_DEFAULT_BRANCH = 'main';
   627|
   628|function readEnv(name: string): string {
   629|  return (typeof process.env[name] === 'string' ? process.env[name] : '').trim();
   630|}
   631|
   632|function parseGithubRepoUrl(value: string): { owner: string; repo: string } | null {
   633|  const match = value.match(/github\.com[:/]([^/\s]+)\/([^/.\s]+)(?:\.git)?/i);
