   647|      {
   648|        headers: {
   649|          Authorization: `Bearer ${token}`,
   650|          Accept: 'application/vnd.github+json',
   651|        },
   652|        signal: AbortSignal.timeout(10000),
   653|      },
   654|    );
   655|    if (!res.ok) return null;
   656|    const data = await res.json() as { object?: { sha?: string } };
