   663|async function commitFilesViaGitDataApi(
   664|  filePaths: string[],
   665|  branch: string,
   666|): Promise<{ commitSha: string; commitUrl: string; branch: string }> {
   667|  const repoUrl = readEnv('GITHUB_REPO_URL');
   668|  const token = readEnv('GITHUB_TOKEN');
   669|  const repoInfo = parseGithubRepoUrl(repoUrl);
   670|  if (!repoInfo) throw new Error('GITHUB_REPO_URL is missing or invalid.');
   671|  if (!token) throw new Error('GITHUB_TOKEN is missing.');
   672|
   673|  const headers = {
   674|    Authorization: `Bearer ${token}`,
   675|    Accept: 'application/vnd.github+json',
   676|    'Content-Type': 'application/json',
   677|  };
   678|
   679|  // Read the branch ref
   680|  const refRes = await fetch(
   681|    `${GITHUB_API_BASE_URL}/repos/${repoInfo.owner}/${repoInfo.repo}/git/ref/heads/${encodeURIComponent(branch)}`,
   682|    { headers, signal: AbortSignal.timeout(10000) },
   683|  );
   684|  if (!refRes.ok) throw new Error(`GitHub branch ref lookup failed: ${refRes.status}`);
   685|  const refData = await refRes.json() as { object?: { sha?: string } };
   686|  const baseCommitSha = refData.object?.sha;
   687|  if (!baseCommitSha) throw new Error('GitHub branch ref did not include a commit SHA.');
   688|
   689|  // Get the base commit's tree
   690|  const commitRes = await fetch(
   691|    `${GITHUB_API_BASE_URL}/repos/${repoInfo.owner}/${repoInfo.repo}/git/commits/${encodeURIComponent(baseCommitSha)}`,
   692|    { headers, signal: AbortSignal.timeout(10000) },
   693|  );
   694|  if (!commitRes.ok) throw new Error(`GitHub base commit lookup failed: ${commitRes.status}`);
   695|  const commitData = await commitRes.json() as { tree?: { sha?: string } };
   696|  const baseTreeSha = commitData.tree?.sha;
   697|  if (!baseTreeSha) throw new Error('GitHub base commit did not include a tree SHA.');
   698|
   699|  // Create the new tree with the changed files
   700|  const tree = await Promise.all(filePaths.map(async (repoPath) => ({
   701|    path: repoPath,
   702|    mode: '100644' as const,
   703|    type: 'blob' as const,
   704|    content: await readFile(path.join(DEFAULT_PROJECT_ROOT, repoPath), 'utf8'),
   705|  })));
   706|
   707|  const treeRes = await fetch(
   708|    `${GITHUB_API_BASE_URL}/repos/${repoInfo.owner}/${repoInfo.repo}/git/trees`,
   709|    {
   710|      method: 'POST',
   711|      headers,
   712|      body: JSON.stringify({ base_tree: baseTreeSha, tree }),
   713|      signal: AbortSignal.timeout(15000),
   714|    },
   715|  );
   716|  if (!treeRes.ok) throw new Error(`GitHub tree creation failed: ${treeRes.status}`);
   717|  const treeData = await treeRes.json() as { sha?: string };
   718|  const newTreeSha = treeData.sha;
   719|  if (!newTreeSha) throw new Error('GitHub tree creation did not return a tree SHA.');
   720|
   721|  // Create the commit
   722|  const newCommitRes = await fetch(
   723|    `${GITHUB_API_BASE_URL}/repos/${repoInfo.owner}/${repoInfo.repo}/git/commits`,
   724|    {
   725|      method: 'POST',
   726|      headers,
   727|      body: JSON.stringify({
   728|        message: `IVX autonomous coder: ${new Date().toISOString()}`,
   729|        tree: newTreeSha,
   730|        parents: [baseCommitSha],
   731|      }),
   732|      signal: AbortSignal.timeout(15000),
   733|    },
   734|  );
   735|  if (!newCommitRes.ok) throw new Error(`GitHub commit creation failed: ${newCommitRes.status}`);
   736|  const newCommitData = await newCommitRes.json() as { sha?: string };
   737|  const commitSha = newCommitData.sha;
   738|  if (!commitSha) throw new Error('GitHub commit creation did not return a commit SHA.');
   739|
   740|  // Update the branch ref
   741|  const updateRes = await fetch(
   742|    `${GITHUB_API_BASE_URL}/repos/${repoInfo.owner}/${repoInfo.repo}/git/refs/heads/${encodeURIComponent(branch)}`,
   743|    {
   744|      method: 'PATCH',
   745|      headers,
   746|      body: JSON.stringify({ sha: commitSha, force: false }),
   747|      signal: AbortSignal.timeout(10000),
   748|    },
   749|  );
   750|  if (!updateRes.ok) throw new Error(`GitHub branch update failed: ${updateRes.status}`);
   751|
   752|  return {
   753|    commitSha,
   754|    commitUrl: `https://github.com/${repoInfo.owner}/${repoInfo.repo}/commit/${commitSha}`,
   755|    branch,
   756|  };
   757|}
