import { gzipSync } from 'node:zlib';
import { readFileSync } from 'node:fs';

const ownerAt = readFileSync('/tmp/owner_at', 'utf8').trim();

const files = [
  {
    path: 'backend/services/ivx-autonomous-coder.ts',
    message: 'IVX autonomous coder hardening: cost/resource controls (Phase 12) + stage timeouts (Phase 5) + production rollback (Phase 16) + cancellation + heartbeat. Adds llmCallCount/estimatedTokensUsed/tokenBudgetExceeded/rollbackTriggered/rollbackCommitSha/rollbackError to proof. DEFAULT_MAX_RUNTIME_MS=8m, DEFAULT_MAX_LLM_CALLS=MAX_ITERATIONS*MAX_LLM_ATTEMPTS, DEFAULT_MAX_TOKEN_BUDGET=60k. rollbackProductionDeploy() reverts to parent SHA + redeploys on verify-fail. finalStatus union adds CANCELED. checkStop() at stage boundaries. All 25 tests pass.',
  },
  {
    path: 'backend/ivx-autonomous-coder.test.ts',
    message: 'IVX autonomous coder: 10 new regression tests G16-G25 (Phase 17). G16 LLM timeout BLOCKED, G17 retry-and-recovery, G18 truncated response, G19 unsafe-path rejection, G20 GitHub push failure FAILED, G21 rollback on verify-fail, G22 rollback-fail FAILED, G23 cancellation CANCELED, G24 heartbeat at stage boundaries, G25 TOKEN_BUDGET_EXCEEDED. 25 tests total (15 original + 10 new), all pass. Test fixtures updated for new proof fields.',
  },
];

for (const f of files) {
  const content = readFileSync(f.path, 'utf8');
  const gz = gzipSync(Buffer.from(content, 'utf8')).toString('base64');
  const body = {
    action: 'github_commit_file',
    input: {
      path: f.path,
      content: gz,
      contentEncoding: 'gzip-base64',
      message: f.message,
    },
    confirm: true,
    confirmText: 'CONFIRM_IVX_GITHUB_WRITE',
  };
  const res = await fetch('https://api.ivxholding.com/api/ivx/developer-deploy/action', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${ownerAt}` },
    body: JSON.stringify(body),
  });
  const text = await res.text();
  console.log(`commit ${f.path}: HTTP ${res.status}`);
  try {
    const j = JSON.parse(text);
    console.log('  commitSha:', j.commitSha || j.result?.commitSha || j.output?.commitSha || 'see-below');
    console.log('  raw:', JSON.stringify(j).slice(0, 400));
  } catch {
    console.log('  raw:', text.slice(0, 400));
  }
}

