// Live LLM-driven test (Phase 7): change PILOT-2 → PILOT-3.
// This goal does NOT match the deterministic fallback (which only fires for
// PILOT-1 → PILOT-2), so the engine MUST use the LLM path. With the 45s timeout
// + MAX_LLM_ATTEMPTS=2 + scoped typecheck + cost controls, it either COMPLETED
// with a real commit or BLOCKS with a real reason (no infinite hang).
import { readFileSync } from 'node:fs';

const ownerAt = readFileSync('/tmp/owner_at', 'utf8').trim();
const runId = `pilot7-${Date.now()}`;
const message = `Autonomous coder: change the visible version label in the IVX owner dashboard from AUTONOMOUS-CODER-PILOT-2 to AUTONOMOUS-CODER-PILOT-3. Run targeted tests, typecheck, create a commit, but do not deploy. (runId=${runId})`;

const res = await fetch('https://api.ivxholding.com/api/ivx/owner-ai', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${ownerAt}` },
  body: JSON.stringify({ message }),
});
const text = await res.text();
console.log('HTTP', res.status);
try {
  const j = JSON.parse(text);
  console.log('executionStatus.taskId:', j.executionStatus?.taskId);
  console.log('executionStatus.status:', j.executionStatus?.status);
  console.log('executionStatus.stage:', j.executionStatus?.stage);
  console.log('executionStatus.category:', j.executionStatus?.category);
  console.log('executionStatus.httpStatus:', j.executionStatus?.httpStatus);
  console.log('executionStatus.statusUrl:', j.executionStatus?.statusUrl);
  console.log('answer (first 1500):', (j.answer || j.message || '').slice(0, 1500));
  if (j.executionStatus?.taskId) {
    const { writeFileSync } = await import('node:fs');
    writeFileSync('/tmp/pilot7_taskid.txt', j.executionStatus.taskId);
  }
} catch {
  console.log('raw:', text.slice(0, 1500));
}

